return {
  on_review = function(ctx)
    local short = 13000 - ctx.here.stock.Goods
    if short > 0 then ctx.order("Goods", short) end
  end,
}

return ops.policy {
  classify = ops.roles.manual { Mine = "supply", Dome = "demand" },
  target = { supply = ops.drain {}, demand = ops.fill {} },
}

return ops.policy {
  classify = ops.roles.manual { Mine = "supply", Junction = "relay", Dome = "demand" },
  target = {
    supply = ops.drain {},
    relay = ops.pass_through {},
    demand = ops.fill {},
  },
  plan = ops.lookahead {},
}

return ops.policy {
  classify = ops.roles.manual { Mine = "supply", Dome = "demand" },
  target = {
    supply = ops.drain {},
    demand = ops.min_max { min = 20000, max = 30000 },
  },
}

return ops.policy {
  classify = ops.roles.manual { Mine = "supply", Factory = "demand", Dome = "demand" },
  target = { supply = ops.drain {}, demand = ops.fill {} },
  plan = ops.lookahead {},
}

return ops.policy {
  classify = ops.roles.manual {
    Farm = { Food = "supply", Metals = "demand" },
    Mine = { Metals = "supply", Food = "demand" },
    Depot = "relay",
    Plant = { Polymers = "supply", Metals = "demand" },
    Dome = "demand",
  },
  target = { supply = ops.drain {}, demand = ops.fill {}, relay = ops.pass_through {} },
  plan = ops.lookahead {},
  allocate = ops.priority {},
}

return ops.policy {
  classify = ops.roles.manual { Mine = "supply", Dome = "demand" },
  target = {
    supply = ops.drain {},
    demand = ops.fill {},
  },
}

return ops.policy {
  classify = ops.roles.manual { Mine = "supply", Factory = "demand", Dome = "demand" },
  target = { supply = ops.drain {}, demand = ops.fill {} },
  plan = ops.lookahead {},
}

return ops.policy {
  classify = ops.roles.manual { Mine = "supply", Dome = "demand" },
  target = {
    supply = ops.drain {},
    demand = ops.min_max { min = 20000, max = 30000 },
  },
}

return ops.policy {
  classify = function(site, ctx)
    if site.station == "Mine" then return "supply" end
    if site.station == "Dome" then return "demand" end
    return "relay"
  end,
  target = {
    supply = ops.drain {},
    relay = ops.pass_through {},
    demand = function(site, ctx)
      -- Keep the dome two thirds full.
      return math.floor(site.capacity * 2 / 3)
    end,
  },
}

return mars.line {
  id = "outpost",
  title = "Outpost",
  duration = sols(5),
  stations = {
    mars.small_station {
      id = "Mine",
      stock = { Metals = 10 },
      buildings = { mars.extractor { resource = "Metals", rate = 30 } },
    },
    mars.large_station {
      id = "Dome",
      stock = { Metals = 20 },
      buildings = { mars.consumer { resource = "Metals", rate = 20, variability = 15 } },
    },
  },
  distances = 40000,
  trains = { mars.train { id = "T1", start = "Mine" } },
}

local depot = station {
  id = "Depot",
  resources = { Malt = { capacity = "unlimited", initial = 200 } },
}

local shop = station {
  id = "Shop",
  resources = { "Beer", "Malt" },
  consumers = {
    consumer { resource = "Beer", poisson = poisson { per_sol = 12 }, unmet = "backorder" },
  },
  converters = {
    converter { inputs = { Malt = 2 }, outputs = { Beer = 1 }, rate = 10 },
  },
  suppliers = {
    supplier { resource = "Beer", lead_time = discrete { { days(1), 3 }, { days(2), 1 } } },
  },
  review = review { period = days(1), offset = minutes(1) },
}

return scenario {
  id = "brewpub",
  title = "Brewpub",
  information = "local",
  duration = sols(14),
  stations = { depot, shop },
  arcs = { arc { from = "Depot", to = "Shop", distance = 600 } },
  vehicles = {
    vehicle { id = "Truck", route = shuttle { stops = { depot, shop } }, speed = 5, capacity = 20 },
  },
}

local stations = {}
for i, stock in ipairs({ 5, 10, 15 }) do
  stations[i] = station { id = "Stop" .. i, resources = { Water = { initial = stock } } }
end

local l = line { stations = stations, distances = { 300, 500 } }

return scenario {
  id = "water-line",
  duration = sols(2),
  parts = { l },
  vehicles = {
    vehicle { id = "Tanker", route = loop { stops = { "Stop1", "Stop2", "Stop3" } }, speed = 4, capacity = 10 },
  },
  arcs = { arc { from = "Stop3", to = "Stop1", distance = 800 } },
}
